"""Build Shopify templates around the shared presentation brand and reference content."""
from pathlib import Path
import json,re
ROOT=Path(__file__).resolve().parents[1];T=ROOT/'theme'
def write(p,s): (T/p).write_text(s,encoding='utf-8')
def section(name,html,settings=None):
    return html+'\n{% schema %}\n'+json.dumps({'name':name,'settings':settings or []})+'\n{% endschema %}'
def template(name,kind):write('templates/'+name+'.json',json.dumps({'sections':{'main':{'type':kind}},'order':['main']},indent=2))
write('layout/theme.liquid','''<!doctype html>
<html lang="{{ request.locale.iso_code }}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="canonical" href="{{ canonical_url }}"><title>{{ page_title | escape }}{% unless page_title contains shop.name %} | {{ shop.name | escape }}{% endunless %}</title>{% if page_description %}<meta name="description" content="{{ page_description | escape }}">{% endif %}{{ content_for_header }}{{ 'reference-structure.css' | asset_url | stylesheet_tag }}{{ 'theme.css' | asset_url | stylesheet_tag }}<style>:root{--red:{{ settings.brand_red | default: '#e21331' }};--cream:{{ settings.brand_cream | default: '#fdf0d6' }};--brown:{{ settings.brand_brown | default: '#77290d' }};}</style><script src="{{ 'theme.js' | asset_url }}" defer></script></head><body><a class="skip-link" href="#MainContent">Skip to content</a>{% section 'header' %}<main id="MainContent" tabindex="-1">{{ content_for_layout }}</main>{% section 'footer' %}<div id="status" role="status" aria-live="polite"></div></body></html>''')
write('sections/header.liquid',section('Header','''<div class="announcement">{{ section.settings.announcement | escape }}</div><header class="site-header"><div class="container header-inner"><a href="{{ routes.root_url }}" aria-label="Home"><img class="brand-logo" src="{{ 'ammammas-logo.svg' | asset_url }}" width="218" height="97" alt="{{ shop.name | escape }}"></a><nav class="main-nav" aria-label="Main navigation">{% if section.settings.menu != blank %}{% for link in section.settings.menu.links %}<a href="{{ link.url }}">{{ link.title | escape }}</a>{% endfor %}{% else %}<details class="nav-shop"><summary>Shop the kitchen</summary><div><a href="{{ routes.all_products_collection_url }}">All Products</a>{% assign category_handles = section.settings.categories | split: ',' %}{% for handle in category_handles %}{% assign clean_handle = handle | strip %}{% assign category = collections[clean_handle] %}{% if category != blank %}<a href="{{ category.url }}">{{ category.title | escape }}</a>{% endif %}{% endfor %}</div></details><a href="/pages/about">Our Story</a><a href="/blogs/recipes">Recipes</a><a href="/pages/contact">Contact</a>{% endif %}</nav><div class="header-tools"><a href="{{ routes.search_url }}" aria-label="Search">{% render 'icon', name: 'search' %}</a><a href="/pages/wishlist" aria-label="Wishlist">{% render 'icon', name: 'heart' %}</a><a href="{{ routes.cart_url }}" aria-label="Shopping bag">{% render 'icon', name: 'bag' %}<span class="bag-count">{{ cart.item_count }}</span></a><button class="mobile-toggle" data-mobile-toggle aria-label="Open menu" aria-expanded="false">{% render 'icon', name: 'menu' %}</button></div></div><nav class="mobile-nav" aria-label="Mobile navigation"><a href="{{ routes.all_products_collection_url }}">All Products</a><a href="/pages/about">Our Story</a><a href="/blogs/recipes">Recipes</a><a href="/pages/contact">Contact</a>{% if section.settings.menu != blank %}{% for link in section.settings.menu.links %}<a href="{{ link.url }}">{{ link.title | escape }}</a>{% endfor %}{% endif %}</nav></header>''',[{'type':'text','id':'announcement','label':'Announcement','default':'Authentic Indian foods. Made with love since 2019.'},{'type':'link_list','id':'menu','label':'Main menu'},{'type':'text','id':'categories','label':'Collection handles','default':'pickles,spices,ready-to-cook,ghee,snacks,fryum-factory,retro'}]))
write('snippets/icon.liquid','''<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true">{% case name %}{% when 'search' %}<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>{% when 'bag' %}<path d="M5 7h14l1 14H4L5 7Z"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/>{% when 'heart' %}<path d="M20 5c-3-3-6-1-8 1-2-2-5-4-8-1-5 5 2 11 8 15 6-4 13-10 8-15Z"/>{% when 'menu' %}<path d="M3 6h18M3 12h18M3 18h18"/>{% endcase %}</svg>''')
write('sections/footer.liquid',section('Footer','''<footer class="site-footer"><div class="container"><div class="footer-grid"><div class="footer-brand"><a href="{{ routes.root_url }}"><img class="brand-logo" src="{{ 'ammammas-footer-logo.svg' | asset_url }}" width="240" height="107" alt="{{ shop.name | escape }}"></a><p>Authentic ready-to-cook Indian food, crafted with your health in mind and designed for ultimate convenience since 2019.</p></div><div><h3>Shop</h3><a href="{{ routes.all_products_collection_url }}">All Products</a>{% for collection in collections %}<a href="{{ collection.url }}">{{ collection.title | escape }}</a>{% endfor %}</div><div><h3>Explore</h3><a href="/pages/about">Our Story</a><a href="/blogs/recipes">Recipes</a><a href="/pages/press">Press & Media</a><a href="/pages/supporters">Supporters</a><a href="/pages/investor-relations">Investor Relations</a><a href="/pages/faq">FAQs</a></div><div><h3>Get in touch</h3><p>Hyderabad, Telangana, India</p><a href="tel:+919347815723">+91 93478 15723</a><a href="mailto:contact@ammammas.in">contact@ammammas.in</a><a href="/pages/contact">Contact Us</a><a href="/pages/shipping-returns">Shipping & Returns</a><a href="/pages/privacy-policy">Privacy Policy</a><a href="/pages/terms-of-service">Terms of Service</a></div></div><div class="footer-bottom"><span>© {{ 'now' | date: '%Y' }} {{ shop.name | escape }}</span><span>Made with Love by Ammamma</span></div></div></footer>'''))
data=json.loads((ROOT/'preview/reference-data.json').read_text(encoding='utf-8'))
home=next(p for p in data['pages'] if p['path']=='/')['content'];hero_imgs=re.findall(r'<img[^>]+src="([^"]+)"',home)
hero_asset=hero_imgs[1].split('/')[-1]
write('sections/home-hero.liquid',section('Heritage hero','''<section class="new-hero"><div class="hero-copy"><span class="eyebrow">{{ section.settings.eyebrow | escape }}</span><h1>{{ section.settings.heading | escape | newline_to_br }}</h1><p>{{ section.settings.description | escape }}</p><div class="hero-actions"><a class="button" href="{{ section.settings.link | default: '/collections/pickles' }}">Shop Pickles</a><a class="text-link" href="{{ routes.all_products_collection_url }}">View All Products</a></div></div><div class="hero-art">{% if section.settings.image != blank %}{{ section.settings.image | image_url: width: 1600 | image_tag: loading: 'eager', widths: '480, 768, 1200, 1600' }}{% else %}<img src="{{ 'HERO_ASSET' | asset_url }}" width="1200" height="1200" alt="Authentic Andhra Pickles" fetchpriority="high">{% endif %}<div class="hero-stamp"><strong>Made<br>with love.</strong><span>Since 2019</span></div></div></section><div class="proof-strip"><span><strong>12</strong> States Available</span><span><strong>40+</strong> Cities Served</span><span><strong>10 lac+</strong> Happy Customers</span></div>'''.replace('HERO_ASSET',hero_asset),[{'type':'text','id':'eyebrow','label':'Eyebrow','default':'New Arrivals This Week'},{'type':'textarea','id':'heading','label':'Heading','default':'Authentic\nAndhra\nPickles.'},{'type':'textarea','id':'description','label':'Description','default':'Hand-pounded spices, Premium quality oils, and recipes passed down through generations. No preservatives, just pure taste.'},{'type':'image_picker','id':'image','label':'Hero image'},{'type':'url','id':'link','label':'Shop link'}]))
index=json.loads((T/'templates/index.json').read_text());index['sections']['s0']={'type':'home-hero'};write('templates/index.json',json.dumps(index,indent=2))
write('snippets/product-card.liquid','''<article class="product-card"><a class="product-photo" href="{{ product.url }}">{% if product.featured_image %}{{ product.featured_image | image_url: width: 700 | image_tag: loading: 'lazy', widths: '300, 450, 700' }}{% else %}{{ 'product-1' | placeholder_svg_tag }}{% endif %}</a><button class="save-product" data-save="{{ product.handle }}" aria-label="Save {{ product.title | escape }}" aria-pressed="false">{% render 'icon', name: 'heart' %}</button><div class="product-meta"><small>{{ product.type | escape }}</small><h3><a href="{{ product.url }}">{{ product.title | escape }}</a></h3><div class="product-price">{{ product.price | money }}</div></div><a class="button" href="{{ product.url }}">{% if product.available %}Choose options{% else %}View product{% endif %}</a></article>''')
for i,heading in [(1,'Bestselling Products'),(2,'New Arrivals')]:
    p=T/'sections'/f'home-{i:02}.liquid';snapshot=p.read_text(encoding='utf-8').split('{% schema %}')[0]
    html='''{% assign featured = section.settings.collection %}{% if featured != blank %}<section class="container catalog-section"><div class="section-heading"><h2>{{ section.settings.heading | escape }}</h2><a href="{{ featured.url }}">View All Products</a></div><div class="product-grid">{% for product in featured.products limit: 8 %}{% render 'product-card', product: product %}{% endfor %}</div></section>{% else %}<div class="reference-content">'''+snapshot+'''</div>{% endif %}'''
    p.write_text(section(heading,html,[{'type':'text','id':'heading','label':'Heading','default':heading},{'type':'collection','id':'collection','label':'Live collection (replace captured products)'}]),encoding='utf-8')
write('sections/main-product.liquid',section('Product','''<div class="container breadcrumbs"><a href="{{ routes.root_url }}">Home</a> / <a href="{{ routes.all_products_collection_url }}">Products</a> / {{ product.title | escape }}</div><section class="container product-detail"><div class="product-gallery">{% if product.featured_image %}{{ product.featured_image | image_url: width: 1400 | image_tag: class: 'main-photo', id: 'main-product-photo', loading: 'eager' }}{% endif %}<div class="gallery-thumbs">{% for image in product.images %}<button data-photo="{{ image | image_url: width: 1400 }}" aria-label="View image {{ forloop.index }}">{{ image | image_url: width: 150 | image_tag: loading: 'lazy' }}</button>{% endfor %}</div></div><div class="detail-copy"><span class="eyebrow">{{ product.type | escape }}</span><h1>{{ product.title | escape }}</h1><p class="detail-price" data-product-price>{{ product.selected_or_first_available_variant.price | money }}</p><div>{{ product.description }}</div>{% form 'product', product %}<label for="ProductVariant-{{ section.id }}">Size / option</label><select id="ProductVariant-{{ section.id }}" name="id" data-variant-select>{% for variant in product.variants %}<option value="{{ variant.id }}" data-price="{{ variant.price | money | escape }}" data-available="{{ variant.available }}" {% if variant == product.selected_or_first_available_variant %}selected{% endif %}>{{ variant.title | escape }}{% unless variant.available %} — Out of Stock{% endunless %}</option>{% endfor %}</select><div class="purchase-row"><label class="sr-only" for="Quantity-{{ section.id }}">Quantity</label><input id="Quantity-{{ section.id }}" name="quantity" type="number" value="1" min="1"><button class="button" type="submit" name="add" data-product-submit {% unless product.selected_or_first_available_variant.available %}disabled{% endunless %}>{% if product.selected_or_first_available_variant.available %}Add to Cart{% else %}Out of Stock{% endif %}</button></div>{{ form.errors | default_errors }}{% endform %}<button data-save="{{ product.handle }}" aria-pressed="false">Save to wishlist</button></div></section><script type="application/ld+json">{{ product | structured_data }}</script>'''))
template('product','main-product')
write('sections/main-collection.liquid',section('Collection','''<section class="container page-heading catalog-illustrated">{% render 'catalog-art', handle: collection.handle %}<span class="eyebrow">Ammamma’s kitchen</span><h1>{{ collection.title | escape }}</h1><div>{{ collection.description }}</div><form method="get"><label for="SortBy">Sort products</label><select id="SortBy" name="sort_by">{% for option in collection.sort_options %}<option value="{{ option.value }}" {% if option.value == collection.sort_by %}selected{% endif %}>{{ option.name | escape }}</option>{% endfor %}</select><button class="button">Sort</button></form></section><section class="container">{% paginate collection.products by 24 %}<div class="product-grid">{% for product in collection.products %}{% render 'product-card', product: product %}{% else %}<p>No products found.</p>{% endfor %}</div>{{ paginate | default_pagination }}{% endpaginate %}</section>'''))
template('collection','main-collection')
write('sections/main-cart.liquid',section('Cart','''<section class="container content-page"><h1>Your bag</h1>{% if cart.empty? %}<p>Your bag is empty.</p><a class="button" href="{{ routes.all_products_collection_url }}">Shop All Products</a>{% else %}{% form 'cart', cart %}{% for item in cart.items %}<div class="cart-line">{{ item.image | image_url: width: 150 | image_tag: loading: 'lazy' }}<div><h3><a href="{{ item.url }}">{{ item.product.title | escape }}</a></h3><p>{{ item.variant.title | escape }} · {{ item.final_line_price | money }}</p><label for="Quantity-{{ item.key }}">Quantity</label><input id="Quantity-{{ item.key }}" name="updates[]" type="number" value="{{ item.quantity }}" min="0"></div><a href="{{ item.url_to_remove }}">Remove</a></div>{% endfor %}<div class="cart-total"><span>Subtotal</span><span>{{ cart.total_price | money }}</span></div><p>Shipping and taxes calculated at checkout.</p><button type="submit" name="update">Update bag</button><button class="button" type="submit" name="checkout">Checkout</button>{% endform %}{% endif %}</section>'''))
template('cart','main-cart')
write('sections/main-page.liquid',section('Page','''<section class="container content-page"><h1>{{ page.title | escape }}</h1><div>{{ page.content }}</div></section>'''));template('page','main-page')
write('sections/main-search.liquid',section('Search','''<section class="container content-page"><h1>Search</h1><form action="{{ routes.search_url }}" method="get"><input name="q" type="search" value="{{ search.terms | escape }}" aria-label="Search products"><input name="type" type="hidden" value="product"><button class="button">Search</button></form>{% if search.performed %}{% paginate search.results by 24 %}<div class="product-grid">{% for product in search.results %}{% render 'product-card', product: product %}{% else %}<p>No products found.</p>{% endfor %}</div>{{ paginate | default_pagination }}{% endpaginate %}{% endif %}</section>'''));template('search','main-search')
write('sections/main-blog.liquid',section('Recipes','''<section class="container content-page"><h1>{{ blog.title | escape }}</h1>{% paginate blog.articles by 12 %}<div class="product-grid">{% for article in blog.articles %}<article>{% if article.image %}<a href="{{ article.url }}">{{ article.image | image_url: width: 700 | image_tag: loading: 'lazy' }}</a>{% endif %}<h2><a href="{{ article.url }}">{{ article.title | escape }}</a></h2><div>{{ article.excerpt }}</div></article>{% endfor %}</div>{{ paginate | default_pagination }}{% endpaginate %}</section>'''));template('blog','main-blog')
write('sections/main-article.liquid',section('Recipe article','''<article class="container content-page"><h1>{{ article.title | escape }}</h1>{% if article.image %}{{ article.image | image_url: width: 1200 | image_tag: loading: 'eager' }}{% endif %}<div>{{ article.content }}</div></article>'''));template('article','main-article')
write('sections/main-404.liquid',section('Page not found','''<section class="container empty-state"><h1>Page not found</h1><a class="button" href="{{ routes.root_url }}">Back to home</a></section>'''));template('404','main-404')
write('sections/main-contact.liquid',section('Contact form','''<section class="container content-page"><h1>Contact Us</h1><p>Have a question, suggestion, or just want to say hello? We'd love to hear from you.</p>{% form 'contact' %}{{ form.errors | default_errors }}{% if form.posted_successfully? %}<p role="status">Thank you. Your message has been sent.</p>{% endif %}<label for="ContactName">Name</label><input id="ContactName" name="contact[name]" autocomplete="name" required><label for="ContactEmail">Email</label><input id="ContactEmail" name="contact[email]" type="email" autocomplete="email" required><label for="ContactSubject">Subject</label><input id="ContactSubject" name="contact[subject]"><label for="ContactBody">Message</label><textarea id="ContactBody" name="contact[body]" rows="6" required></textarea><button class="button">Send Message</button>{% endform %}</section>'''));template('page.contact','main-contact')
write('sections/main-wishlist.liquid',section('Wishlist','''<section class="container content-page"><h1>Wishlist</h1><div class="product-grid" data-wishlist-products></div><p data-wishlist-empty>Your wishlist is empty. Save your favourites while you browse.</p></section>'''));template('page.wishlist','main-wishlist')
write('config/settings_schema.json',json.dumps([{'name':'theme_info','theme_name':'Ammammas Heritage','theme_version':'0.1.0','theme_author':'Rashomone','theme_documentation_url':'https://shopify.dev/docs/storefronts/themes','theme_support_url':'https://www.ammammas.in/contact'},{'name':'Presentation colours','settings':[{'type':'color','id':'brand_red','label':'Brand red','default':'#e21331'},{'type':'color','id':'brand_cream','label':'Brand cream','default':'#fdf0d6'},{'type':'color','id':'brand_brown','label':'Brand brown','default':'#77290d'}]}],indent=2))
write('config/settings_data.json',json.dumps({'current':{'brand_red':'#e21331','brand_cream':'#fdf0d6','brand_brown':'#77290d'}}))
write('locales/en.default.json',json.dumps({'general':{'accessibility':{'skip_to_content':'Skip to content'}}}))
print('Native Shopify theme foundation generated; store validation pending access.')

# Apply the shared heritage presentation after the Shopify foundation.
import runpy
runpy.run_path(str(ROOT/"scripts/build_heritage.py"))

runpy.run_path(str(ROOT/"scripts/build_story.py"))
